INSERT INTO item_types (code, name, category, sprite, label_prefix, slot_kinds, height, ports, description, income_per_sec, max_tier, shield_pct, shop_group, boost_pct, radio, site_boost) VALUES
  ('r2620xm', 'Cisco 2620XM router', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Fa0/0","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'An older modular router: one FastEthernet port and a console port. Boosts every device behind it.', 0, 3, 0, 'network', 25, 'none', 0),
  ('r2621xm', 'Cisco 2621XM router', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Fa0/0","kind":"copper","role":"mdi"},{"name":"Fa0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'Like the 2620XM with a second FastEthernet port, so it can route between two networks. Boosts every device behind it.', 0, 3, 0, 'network', 28, 'none', 0),
  ('r1841', 'Cisco 1841 router', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Fa0/0","kind":"copper","role":"mdi"},{"name":"Fa0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'A classic branch router from CCNA labs: 2x FastEthernet. Boosts every device behind it.', 0, 3, 0, 'network', 32, 'none', 0),
  ('pt_router', 'PT-Router', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Fa0/0","kind":"copper","role":"mdi"},{"name":"Fa1/0","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'Packet Tracer’s generic router: an empty chassis you can fill with interface modules. Boosts every device behind it.', 0, 3, 0, 'network', 38, 'none', 0),
  ('r2811', 'Cisco 2811 router', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Fa0/0","kind":"copper","role":"mdi"},{"name":"Fa0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'An Integrated Services Router that can do NAT and DHCP for a small office. Fitted with a wireless card here, so it is also a Wi-Fi access point. Boosts every device behind it.', 0, 3, 0, 'network', 45, 'ap', 0),
  ('r1941', 'Cisco 1941 ISR', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Gi0/0","kind":"copper","role":"mdi"},{"name":"Gi0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'Second-generation ISR with 2x Gigabit Ethernet. Boosts every device behind it.', 0, 3, 0, 'network', 50, 'none', 0),
  ('r4321', 'Cisco ISR 4321', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Gi0/0/0","kind":"copper","role":"mdi"},{"name":"Gi0/0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'A compact fourth-generation ISR. Interfaces are numbered slot/subslot/port, like Gi0/0/0. Boosts every device behind it.', 0, 3, 0, 'network', 55, 'none', 0),
  ('r2901', 'Cisco 2901 ISR', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Gi0/0","kind":"copper","role":"mdi"},{"name":"Gi0/1","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'A branch-office ISR with 2x Gigabit and module bays. Boosts every device behind it.', 0, 3, 0, 'network', 55, 'none', 0),
  ('r2911', 'Cisco 2911 ISR', 'device', 'router1u', 'R', 'shelf,rack', 1, '[{"name":"Gi0/0","kind":"copper","role":"mdi"},{"name":"Gi0/1","kind":"copper","role":"mdi"},{"name":"Gi0/2","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'The 2901’s bigger sibling: 3x Gigabit, so one router can join three networks. Boosts every device behind it.', 0, 3, 0, 'network', 58, 'none', 0),
  ('r8200', 'Catalyst 8200 edge router', 'device', 'router1u', 'R', 'rack', 1, '[{"name":"Gi0/0/0","kind":"fiber"},{"name":"Gi0/0/1","kind":"fiber"},{"name":"Gi0/0/2","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'A modern edge router for a datacentre’s connection to the world: fibre uplinks and SD-WAN. Boosts every device behind it.', 0, 3, 0, 'network', 80, 'none', 0),
  ('pt_hub', 'PT-Hub', 'device', 'hub', 'HUB', 'shelf,desk,floor', 1, '[{"name":"Port1","kind":"copper","role":"mdix"},{"name":"Port2","kind":"copper","role":"mdix"},{"name":"Port3","kind":"copper","role":"mdix"},{"name":"Port4","kind":"copper","role":"mdix"}]', 'A hub repeats every frame out of every port, so all devices share the bandwidth and collide. Cheap, but a switch is far better. Boosts every device behind it a little.', 0, 3, 0, 'network', 10, 'none', 0),
  ('pt_switch', 'PT-Switch', 'device', 'switch1u', 'SW', 'shelf,rack', 1, '[{"name":"Fa0/1","kind":"copper","role":"mdix"},{"name":"Fa0/2","kind":"copper","role":"mdix"},{"name":"Fa0/3","kind":"copper","role":"mdix"},{"name":"Fa0/4","kind":"copper","role":"mdix"},{"name":"Fa0/5","kind":"copper","role":"mdix"},{"name":"Fa0/6","kind":"copper","role":"mdix"}]', 'Packet Tracer’s generic switch: it learns MAC addresses and only sends each frame where it needs to go. Boosts every device behind it.', 0, 3, 0, 'network', 25, 'none', 0),
  ('sw2950', 'Catalyst 2950 switch', 'device', 'switch1u', 'SW', 'shelf,rack', 1, '[{"name":"Fa0/1","kind":"copper","role":"mdix"},{"name":"Fa0/2","kind":"copper","role":"mdix"},{"name":"Fa0/3","kind":"copper","role":"mdix"},{"name":"Fa0/4","kind":"copper","role":"mdix"},{"name":"Fa0/5","kind":"copper","role":"mdix"},{"name":"Fa0/6","kind":"copper","role":"mdix"},{"name":"Fa0/7","kind":"copper","role":"mdix"},{"name":"Fa0/8","kind":"copper","role":"mdix"},{"name":"Con0","kind":"console"}]', 'A legacy Layer 2 Catalyst: FastEthernet only, no Gigabit uplink. Boosts every device behind it.', 0, 3, 0, 'network', 30, 'none', 0),
  ('sw3560', 'Catalyst 3560-24PS switch', 'device', 'switch1u', 'SW', 'rack', 1, '[{"name":"Fa0/1","kind":"copper","role":"mdix"},{"name":"Fa0/2","kind":"copper","role":"mdix"},{"name":"Fa0/3","kind":"copper","role":"mdix"},{"name":"Fa0/4","kind":"copper","role":"mdix"},{"name":"Fa0/5","kind":"copper","role":"mdix"},{"name":"Fa0/6","kind":"copper","role":"mdix"},{"name":"Fa0/7","kind":"copper","role":"mdix"},{"name":"Fa0/8","kind":"copper","role":"mdix"},{"name":"Gi0/1","kind":"fiber"},{"name":"Con0","kind":"console"}]', 'A Layer 3 switch: it can route between VLANs itself. PS means Power over Ethernet, so it can power IP phones and access points through the cable. Boosts every device behind it.', 0, 3, 0, 'network', 55, 'none', 0),
  ('sw3650', 'Catalyst 3650 switch', 'device', 'switch1u', 'SW', 'rack', 1, '[{"name":"Gi1/0/1","kind":"copper","role":"mdix"},{"name":"Gi1/0/2","kind":"copper","role":"mdix"},{"name":"Gi1/0/3","kind":"copper","role":"mdix"},{"name":"Gi1/0/4","kind":"copper","role":"mdix"},{"name":"Gi1/0/5","kind":"copper","role":"mdix"},{"name":"Gi1/0/6","kind":"copper","role":"mdix"},{"name":"Gi1/0/7","kind":"copper","role":"mdix"},{"name":"Gi1/0/8","kind":"copper","role":"mdix"},{"name":"Gi1/1/1","kind":"fiber"},{"name":"Gi1/1/2","kind":"fiber"},{"name":"Con0","kind":"console"}]', 'A Layer 3 Gigabit switch for the core of a network, with fibre uplinks. Boosts every device behind it.', 0, 3, 0, 'network', 65, 'none', 0),
  ('ap_pt', 'AP-PT access point', 'device', 'ap', 'AP', 'shelf,floor', 1, '[{"name":"Port0","kind":"copper","role":"mdi"}]', 'A standalone access point: cable it to a switch or router, and phones, tablets and IoT devices in the same room connect over Wi-Fi. Boosts the wireless devices using it.', 0, 3, 0, 'wireless', 15, 'ap', 0),
  ('lap_pt', 'LAP-PT lightweight AP', 'device', 'ap', 'LAP', 'floor', 1, '[{"name":"Gi0","kind":"copper","role":"mdi"}]', 'A lightweight access point does nothing on its own: it needs a Wireless LAN Controller online in the same building to tell it what to do. Boosts the wireless devices using it.', 0, 3, 0, 'wireless', 30, 'lap', 0),
  ('wlc_pt', 'Wireless LAN Controller', 'device', 'wlc1u', 'WLC', 'rack', 1, '[{"name":"Gi1","kind":"copper","role":"mdi"},{"name":"Gi2","kind":"copper","role":"mdi"},{"name":"Con0","kind":"console"}]', 'Manages every lightweight access point (LAP) in the building from one place: settings, channels and security.', 0, 3, 0, 'wireless', 0, 'wlc', 0),
  ('dsl_modem', 'DSL modem', 'device', 'modem', 'MDM', 'shelf,floor', 1, '[{"name":"WAN","kind":"copper","role":"mdi"},{"name":"Eth0","kind":"copper"}]', 'Brings the internet in over a telephone line. Goes between the ISP box and your router. Boosts every device behind it a little.', 0, 3, 0, 'security', 8, 'none', 0),
  ('cable_modem', 'Cable modem', 'device', 'modem', 'MDM', 'shelf,floor', 1, '[{"name":"WAN","kind":"copper","role":"mdi"},{"name":"Eth0","kind":"copper"}]', 'Brings the internet in over the TV cable network, faster than DSL. Goes between the ISP box and your router. Boosts every device behind it a little.', 0, 3, 0, 'security', 12, 'none', 0),
  ('asa5505', 'ASA 5505 firewall', 'device', 'asa1u', 'ASA', 'shelf,rack', 1, '[{"name":"Eth0/0","kind":"copper","role":"mdi"},{"name":"Eth0/1","kind":"copper"},{"name":"Eth0/2","kind":"copper"},{"name":"Con0","kind":"console"}]', 'A small-office Cisco firewall with a built-in switch. Online, it blocks part of every breach.', 0, 3, 15, 'security', 0, 'none', 0),
  ('net_ctrl', 'Network Controller', 'device', 'ctl1u', 'NC', 'rack', 1, '[{"name":"Gi0","kind":"copper","role":"mdi"}]', 'Centralised management: one controller configures and monitors the whole network, so everything runs better. Online, every end device in the building earns 10% more.', 0, 3, 0, 'security', 0, 'none', 10),
  ('smartphone', 'Smartphone', 'device', 'phone', 'PH', 'floor,desk', 1, '[]', 'Connects over Wi-Fi: it needs an access point or a wireless router in the same room. Earns once it is online.', 12, 3, 0, 'end', 0, 'client', 0),
  ('tablet', 'Tablet', 'device', 'tablet', 'TAB', 'floor,desk', 1, '[]', 'A wireless-only device like the smartphone, with a bigger screen. Needs Wi-Fi in the same room.', 30, 3, 0, 'end', 0, 'client', 0),
  ('printer', 'Network printer', 'device', 'printer', 'PRN', 'floor,desk', 1, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'A printer on the network that everyone can share. Cable it to a switch.', 15, 3, 0, 'end', 0, 'none', 0),
  ('smart_tv', 'Smart TV', 'device', 'tv', 'TV', 'floor', 1, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Streams from the network. Cable it to a switch.', 60, 3, 0, 'end', 0, 'none', 0),
  ('ip_phone', 'IP phone (VoIP)', 'device', 'ipphone', 'IPP', 'desk,floor', 1, '[{"name":"Switch","kind":"copper","role":"mdi"},{"name":"PC","kind":"copper"}]', 'A phone that makes calls over the network (Voice over IP). It has a second port so a PC can plug in through it. Switches with PoE can power it through the cable.', 150, 3, 0, 'end', 0, 'none', 0),
  ('srv_dhcp', 'DHCP server', 'device', 'rack2u', 'DHCP', 'rack', 2, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Hands out IP addresses, gateways and DNS settings to every device that joins the network.', 18000, 3, 0, 'end', 0, 'none', 0),
  ('srv_dns', 'DNS server', 'device', 'rack2u', 'DNS', 'rack', 2, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Turns names like netforge.local into IP addresses, so nobody has to remember numbers.', 20000, 3, 0, 'end', 0, 'none', 0),
  ('srv_email', 'Email server', 'device', 'rack2u', 'MAIL', 'rack', 2, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Sends and stores email for your clients using SMTP and POP3.', 22000, 3, 0, 'end', 0, 'none', 0),
  ('srv_file', 'File server', 'device', 'rack2u', 'FILE', 'rack', 2, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Stores shared files and serves them with FTP, so a whole team works from one place.', 26000, 3, 0, 'end', 0, 'none', 0),
  ('srv_db', 'Database server', 'device', 'rack2u', 'DB', 'rack', 2, '[{"name":"Eth0","kind":"copper","role":"mdi"},{"name":"Eth1","kind":"copper","role":"mdi"}]', 'Runs the databases behind websites and apps. Two network ports for redundancy.', 32000, 3, 0, 'end', 0, 'none', 0),
  ('iot_light', 'Smart light', 'device', 'iot_light', 'LGT', 'floor', 1, '[]', 'An IoT bulb you can switch from the network. Connects over Wi-Fi.', 4, 3, 0, 'iot', 0, 'client', 0),
  ('iot_plug', 'Smart plug', 'device', 'iot_plug', 'PLG', 'floor', 1, '[]', 'Switches whatever is plugged into it on and off over the network. Connects over Wi-Fi.', 10, 3, 0, 'iot', 0, 'client', 0),
  ('iot_thermo', 'Smart thermostat', 'device', 'iot_thermo', 'THR', 'floor', 1, '[]', 'Reads the temperature and controls heating and cooling over the network. Connects over Wi-Fi.', 40, 3, 0, 'iot', 0, 'client', 0),
  ('iot_camera', 'IP camera', 'device', 'iot_camera', 'CAM', 'floor', 1, '[]', 'A security camera that streams over the network. Online, it helps catch attacks: it blocks part of every breach. Connects over Wi-Fi.', 0, 3, 5, 'iot', 0, 'client', 0),
  ('iot_waste', 'Waste sensor', 'device', 'iot_sensor', 'WST', 'floor', 1, '[]', 'A smart-city sensor that reports when bins are full. Councils pay for the data. Connects over Wi-Fi.', 380, 3, 0, 'iot', 0, 'client', 0),
  ('iot_env', 'Environment sensor', 'device', 'iot_sensor', 'ENV', 'floor', 1, '[]', 'Measures temperature, humidity and air quality for a smart city. Connects over Wi-Fi.', 450, 3, 0, 'iot', 0, 'client', 0),
  ('iot_parking', 'Parking sensor', 'device', 'iot_sensor', 'PRK', 'floor', 1, '[]', 'Tells drivers which parking spaces are free. Connects over Wi-Fi.', 500, 3, 0, 'iot', 0, 'client', 0),
  ('iot_street', 'Smart street light', 'device', 'iot_street', 'STL', 'floor', 1, '[]', 'Dims and brightens itself as people pass, run from the network. Connects over Wi-Fi.', 3500, 3, 0, 'iot', 0, 'client', 0),
  ('iot_traffic', 'Traffic light controller', 'device', 'iot_traffic', 'TRF', 'floor', 1, '[]', 'Times a junction’s lights from the network to keep traffic moving. Connects over Wi-Fi.', 5500, 3, 0, 'iot', 0, 'client', 0),
  ('iot_plc', 'Industrial controller (PLC)', 'device', 'iot_plc', 'PLC', 'floor', 1, '[{"name":"Eth0","kind":"copper","role":"mdi"}]', 'Runs machines in a factory. Industrial devices are wired for reliability: cable it to a switch.', 14000, 3, 0, 'iot', 0, 'none', 0)
