-- NetForge: the Packet Tracer device catalogue. Generated; run after schema_music.sql. Safe to run again.
-- Routers, switches, a hub, wireless (AP, LAP, WLC), security and WAN, end devices, server roles and IoT,
-- each with its real ports and a description of what it is. Prices and incomes follow the game's curve.
USE netforge;

/* radio: ap = gives Wi-Fi to wireless devices in the same place, lap = like ap but needs an online WLC,
   wlc = Wireless LAN Controller, client = connects over Wi-Fi only (no cable).
   site_boost: percent more for every end device in the place while it is online. */
ALTER TABLE item_types ADD COLUMN IF NOT EXISTS radio ENUM('none','ap','lap','wlc','client') NOT NULL DEFAULT 'none';
ALTER TABLE item_types ADD COLUMN IF NOT EXISTS site_boost SMALLINT UNSIGNED NOT NULL DEFAULT 0;

-- the home router already gives Wi-Fi; switches and routers are now 1U tall
UPDATE item_types SET radio = 'ap' WHERE code = 'home_router';
UPDATE item_types SET height = 1, sprite = 'switch1u' WHERE code = 'switch8';
UPDATE item_types SET height = 1, sprite = 'router1u', slot_kinds = 'shelf,rack' WHERE code = 'router';
UPDATE item_types SET sprite = 'rack2u' WHERE code = 'server';
UPDATE item_types SET name = 'Web server (UCS C220)', description = 'Cisco UCS C220 rack server running a website (HTTP and HTTPS).' WHERE code = 'server';

ON DUPLICATE KEY UPDATE name = VALUES(name), sprite = VALUES(sprite), label_prefix = VALUES(label_prefix), slot_kinds = VALUES(slot_kinds),
  height = VALUES(height), ports = VALUES(ports), description = VALUES(description), income_per_sec = VALUES(income_per_sec),
  shield_pct = VALUES(shield_pct), shop_group = VALUES(shop_group), boost_pct = VALUES(boost_pct), radio = VALUES(radio), site_boost = VALUES(site_boost);

-- in the shop (rows are added once; staff can change prices and levels on Unlocks and prices)
